<?php require_once 'includes.php';if(is_logged_in()){header('Location: profile.php');exit;}$errors=[];$email='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$pw==='')$errors[]='Enter your email and password.';else{$s=db()->prepare('SELECT id,password_hash FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($pw,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$_SESSION['flash']='You are signed in.';header('Location: profile.php');exit;}$errors[]='Email or password is incorrect.';}}page_header('Sign in');?><section class="form-layout"><div class="form-panel"><p class="eyebrow">WELCOME BACK</p><h1>Sign in</h1><p>Your next great journey is waiting.</p><?php if($errors):?><div class="error-list"><ul><?php foreach($errors as $x):?><li><?=e($x)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label class="form-field">Email address<input name="email" type="email" required autocomplete="email" value="<?=e($email)?>"></label><label class="form-field">Password<input name="password" type="password" required autocomplete="current-password"></label><button class="btn btn-primary full-width">Sign in</button></form><p style="margin-top:18px">New here? <a class="text-link" href="signup.php">Create an account</a></p></div></section><?php page_footer();?>